-- Study Abroad country content, BATCH 10: Mexico, Brazil, Argentina, Chile, Egypt.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('mexico', 'brazil', 'argentina', 'chile', 'egypt'));
UPDATE countries SET why_title = 'Why study in Mexico?', why_body = '<p>Mexico has some of Latin America''s oldest universities, a rich culture and costs well below those of the US or Europe. UNAM is ranked 145th in the QS World University Rankings 2027 (press-reported).</p><ul><li>Large public universities and strong private universities such as Tecnológico de Monterrey</li><li>Strong in architecture, engineering, medicine, arts and Spanish language and culture</li><li>Low living costs compared with the US and Europe</li><li>Close to the US and well connected across Latin America</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Stays longer than 180 days require a <strong>temporary resident student visa</strong>, applied for at a Mexican consulate before travel, followed by registration with the National Migration Institute (INM) on arrival.</p><ul><li>Admission letter from a Mexican institution</li><li>Proof of funds: a scholarship letter or a bank statement or financial letter (parents may show funds for applicants under 25)</li><li>Passport, photographs and the consulate application form</li><li>Visa fee: reported at about US$54-$56, depending on the consulate</li><li>On arrival: register with the INM to receive the student residence card</li><li>Work: a temporary student resident can ask the INM for permission to work</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Mexican consulate (SRE) and the INM site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Applications for UNAM and other public universities often follow fixed calendars and, in some cases, entrance exams.</p><ul><li>Academic transcripts and certificates, apostilled and translated into Spanish where required</li><li>Spanish language proof (DELE, SIELE) for Spanish-taught programmes</li><li>Motivation letter and CV for postgraduate programmes</li><li>Entrance exam for some public university programmes</li><li>Passport copy and photographs</li><li>Health insurance with coverage in Mexico (UNAM requires medical and accident insurance)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public universities charge lower fees than private universities. Living costs are low compared with the US and Europe.</p><ul><li>Public universities: tuition is low, and international students may pay more than local students; check each university</li><li>Private universities: roughly US$6,000-$20,000+ a year (estimate)</li><li>Living costs: about US$500-$900 a month; Mexico City is more expensive</li><li>UNAM does not provide student housing, so budget for private rent</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled, with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes; some programmes are in English</li><li>Public universities may require an entrance exam</li></ul>' WHERE slug = 'mexico';
UPDATE countries SET why_title = 'Why study in Brazil?', why_body = '<p>Brazil has the largest higher education system in Latin America, with tuition-free public universities and strong research. USP is ranked 133rd in the QS World University Rankings 2027 (press-reported).</p><ul><li>Public federal and state universities are tuition free</li><li>Strong in agriculture, environment, engineering, medicine and the arts</li><li>Learn Portuguese and experience a large, diverse economy</li><li>Scholarship programmes for students from partner countries (such as PEC-G)</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Students enrolling in a recognised Brazilian course need a <strong>temporary visa for study (VITEM IV)</strong> from a Brazilian embassy or consulate, then register with the Federal Police after arrival.</p><ul><li>Admission letter from a Brazilian institution recognised by the Ministry of Education (MEC)</li><li>Proof of funds or a scholarship letter (the requirement is set by the consulate or programme)</li><li>Passport, photographs and criminal record certificate</li><li>Visa fee: reported between about US$80 and $290, depending on the country, plus any handling fee</li><li>Processing: typically 2-6 weeks</li><li>Register with the Federal Police within 90 days of arrival to get the CRNM card</li><li>Work: VITEM IV holders may not take employment in Brazil</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Brazilian consulate (Itamaraty) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Public universities use their own entrance process or national tests, and some have special places for international students.</p><ul><li>Academic transcripts and certificates, apostilled and translated into Portuguese</li><li>Portuguese proficiency (CELPE-Bras) for Portuguese-taught programmes</li><li>Motivation letter and CV for postgraduate programmes</li><li>Entrance exam where required</li><li>Passport copy and photographs</li><li>Health insurance</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Federal and state public universities are tuition free, though competition for places is high. Private universities charge fees.</p><ul><li>Public universities: tuition free at federal and state universities (admission is competitive)</li><li>Private universities: roughly US$3,000-$10,000+ a year (estimate)</li><li>Living costs: about US$400-$900 a month; São Paulo and Rio are more expensive</li><li>Visa and registration costs apply</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate recognised in Brazil, plus an entrance exam or international admission process</li><li><strong>Master''s and PhD:</strong> a relevant previous degree, a research proposal and, often, a supervisor</li><li><strong>Language:</strong> Portuguese (CELPE-Bras) for most programmes; some postgraduate programmes accept English</li><li>Applicants must be admitted to an MEC-recognised course for a student visa</li></ul>' WHERE slug = 'brazil';
UPDATE countries SET why_title = 'Why study in Argentina?', why_body = '<p>Argentina has strong universities, a vibrant culture and low costs, with public university undergraduate study widely reported as free for foreigners. The University of Buenos Aires (UBA) is ranked 84th in the QS World University Rankings 2027 (press-reported).</p><ul><li>Public universities such as UBA are very well known in Latin America</li><li>Strong in medicine, psychology, social sciences, arts and architecture</li><li>Low living costs compared with Europe and the US</li><li>Spanish immersion in a lively, creative country</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Stays longer than 90 days normally require a <strong>student visa</strong> or a temporary student residence. Citizens of some countries can enter as tourists and apply through the migration office (RADEX) after arrival.</p><ul><li>Admission letter from an Argentine institution</li><li>Passport, photographs and criminal record certificate</li><li>Student visa category (365 days) for stays under a year; temporary student residence for longer study</li><li>Apply through the Argentine consulate or the National Directorate of Migration</li><li>Health insurance is recommended</li><li>Work: part-time work is reported as allowed for students (check current rules)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Argentine consulate (Cancillería) and the National Directorate of Migration site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Public universities such as UBA use a preparatory course (CBC) for undergraduates.</p><ul><li>Academic transcripts and certificates, apostilled and sometimes validated by the Ministry of Education</li><li>Spanish language proof for Spanish-taught programmes</li><li>Motivation letter and CV for postgraduate programmes</li><li>CBC (Ciclo Básico Común) or entry process at public universities</li><li>Passport copy and photographs</li><li>Application fee at some private universities</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public universities are described as free for undergraduates, including foreigners, though policy is under debate. Private universities charge fees.</p><ul><li>Public universities: undergraduate study reported as free (rules may change, so confirm)</li><li>Private universities: roughly US$3,000-$10,000 a year (reported range)</li><li>Living costs: about US$400-$900 a month in Buenos Aires</li><li>University funding protests in 2026 may affect academic calendars</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled, and often a validation process</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher), such as the CELU certificate, for Spanish-taught programmes</li><li>Some programmes ask for entrance exams or interviews</li></ul>' WHERE slug = 'argentina';
UPDATE countries SET why_title = 'Why study in Chile?', why_body = '<p>Chile has some of the best-ranked universities in Latin America. The Pontificia Universidad Católica de Chile is ranked 119th in the QS World University Rankings 2027 (press-reported) and tops the regional ranking.</p><ul><li>Top-ranked universities in Latin America</li><li>Strong in mining, astronomy, environment, engineering and business</li><li>Politically stable and modern country with beautiful geography</li><li>Spanish immersion, with some English-taught options</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Stays longer than 90 days need a <strong>temporary residence for students</strong> visa, applied for from abroad through the SERMIG online system.</p><ul><li>Admission letter from a recognised Chilean institution</li><li>Valid passport and photographs</li><li>Health insurance covering emergencies, hospitalisation and repatriation, valid in Chile</li><li>No fixed amount for proof of funds is published; each university or consulate may ask for evidence of means</li><li>Processing takes about 2 months and approval is not automatic</li><li>Work: sources conflict (30 hours a week without separate authorisation versus no automatic right to work), so check with SERMIG</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official SERMIG (Chile) and the Chilean consulate site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Undergraduate applicants from outside Chile are often evaluated on their school record and, at some universities, on entrance tests.</p><ul><li>Academic transcripts and certificates, apostilled and translated into Spanish</li><li>Spanish language proof for Spanish-taught programmes</li><li>Motivation letter and CV for postgraduate programmes</li><li>Entrance exam or equivalent for some programmes</li><li>Passport copy and photographs</li><li>Health insurance for the visa</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs depend on the university. Leading private and public universities charge tuition, and Chilean public universities are not free for international students.</p><ul><li>Tuition: roughly US$4,000-$12,000 a year for many programmes (estimate; check each university)</li><li>Living costs: about US$600-$1,000 a month; Santiago is more expensive</li><li>Health insurance is required for the visa</li><li>Some universities offer partial scholarships to international students</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for most programmes; some courses offer English</li><li>International applicants must show academic record and, where required, test results</li></ul>' WHERE slug = 'chile';
UPDATE countries SET why_title = 'Why study in Egypt?', why_body = '<p>Egypt has some of the Arab world''s oldest universities, strong programmes in medicine, engineering and Arabic and Islamic studies, and lower costs than many destinations. The government has launched a Study in Egypt initiative to attract international students.</p><ul><li>Historic universities such as Cairo University and Al-Azhar</li><li>Study Arabic and Islamic studies at the source</li><li>International universities such as the American University in Cairo</li><li>Lower costs than most Western destinations</li></ul>', visa_title = 'Student visa and residence permit', visa_body = '<p>Most students enter on a tourist visa or visa on arrival, then convert to a <strong>student residence permit</strong> through their university''s foreign students office after arrival.</p><ul><li>Admission letter from an Egyptian institution</li><li>Entry on a single-entry or visa-on-arrival status; the visa on arrival by digital payment has been reported at about US$36 from August 2026</li><li>Residence permit: arranged through the university and the immigration office (the Mogamma), usually valid for one year and renewed annually</li><li>Passport, photographs, medical tests and admission documents</li><li>Work: sources conflict on whether students may work, so check with the Ministry of Labour</li><li>The government has asked agencies to speed up visa issuance for international students (August 2026)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Egyptian Ministry of Interior and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, and Al-Azhar has its own foreign students office. Public universities often use a central process for international applicants.</p><ul><li>Academic transcripts and certificates, attested</li><li>Language proof (Arabic or English)</li><li>Motivation letter and references for postgraduate programmes</li><li>Medical certificate and passport copies</li><li>Entrance test for some programmes</li><li>Passport photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university. Public universities are much cheaper than private and international universities.</p><ul><li>Public universities: roughly US$1,500-$5,000 a year (reported range)</li><li>American University in Cairo: about US$735 per credit hour for international undergraduates (July 2026, reported)</li><li>Living costs: about EGP 8,000-15,000 a month in Cairo (reported)</li><li>Al-Azhar is reported to offer free tuition and stipends to some students, so check its foreign students office</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate equivalent to the Egyptian Thanaweya Amma, with the required score</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Arabic for most public universities; English for AUC and some programmes</li><li>Medicine and engineering have higher entry requirements</li></ul>' WHERE slug = 'egypt';
COMMIT;
